import{_ as o,o as c,c as d,a3 as a}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Bazel 模块","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Bazel 模块 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/design/bazel-module"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/design/bazel-module"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/bazel-module"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/bazel-module"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/bazel-module"}]]},"headers":[],"relativePath":"zh/xclang/design/bazel-module.md","filePath":"zh/xclang/design/bazel-module.md","lastUpdated":1794509097000}'),l={name:"zh/xclang/design/bazel-module.md"};function i(t,e,s,r,n,g){return c(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="bazel-模块" tabindex="-1">Bazel 模块 <a class="header-anchor" href="#bazel-模块" aria-label="Permalink to &quot;Bazel 模块&quot;">​</a></h1><p>xclang 的 Bazel 模块（<code>packages/bazel</code>）让 C++ 构建保持自包含，并能跨检出目录与机器复用缓存：每个动作读取的工具链与 SDK 文件都是已声明的 Bazel 输入，命令行与构建产物中不包含绝对路径（macOS 主机上的 Xcode SDK 与原生 sanitizer rpath 除外），而且 <code>cc_library</code> 依赖默认静态链接进程序与测试。模块的配置与用法见 <a href="./../integrations/bazel">Bazel</a>，它的 label、标志与特性见 <a href="./../reference/bazel-api">Bazel API</a>。</p><h2 id="每个工具链文件都是声明输入" tabindex="-1">每个工具链文件都是声明输入 <a class="header-anchor" href="#每个工具链文件都是声明输入" aria-label="Permalink to &quot;每个工具链文件都是声明输入&quot;">​</a></h2><p><code>xclang_toolchain</code> 仓库规则按 <code>bazel/versions.bzl</code> 中锁定的 <code>sha256</code> 下载主机工具链压缩包。编译或链接动作从压缩包读取的每个文件都在 <code>cc_toolchain</code> 的 filegroup 中声明：编译用到 <code>bin/</code> 下的可执行文件、<code>clang</code> 的资源头文件、目标平台的 sysroot 头文件及共用的 <code>libc++</code> / <code>mingw-w64</code> 头文件，链接用到目标平台的 sysroot 库与 <code>compiler-rt</code>。模块扩展拉取的厂商 SDK 同样作为输入声明（<a href="#vendor-sdks-as-repositories">见下文</a>）；唯一位于 Bazel 外部的主机路径是 macOS 主机上由 <code>xcrun --show-sdk-path</code> 定位的 Xcode macOS SDK。</p><p>在有 Bazel 模块之前，xclang 的 Bazel 配置直接包装 <code>PATH</code> 上的 <code>clang</code>，不声明任何工具链文件，这从两方面破坏了缓存：</p><ul><li><code>PATH</code> 的任何变动都会使工具链仓库失效，触发整个工作区重新构建。</li><li>升级 <code>PATH</code> 上的 <code>clang</code> 不会改变任何动作输入，构建缓存仍会返回旧编译器生成的目标文件。</li></ul><p>把每个工具链文件声明为动作输入同时解决了这两个问题：升级 <code>xclang</code> 模块会改变所有编译与链接动作的输入摘要并触发重编，而在另一个目录或另一台机器上使用同一发布版本构建则能共享缓存命中。</p><p>代价是沙盒文件布置开销：每次执行编译和链接动作时，Bazel 沙盒都要为数千个已声明的工具链文件创建链接。在 Windows 主机上，Bazel 默认不使用沙盒运行动作（除非开启 <code>--experimental_use_windows_sandbox</code>），因此漏声明的输入会由同一目标在 Linux 与 macOS 上的构建检出；同时，Windows 上 Bazel 默认输出根目录在布置层级较深的工具链与 SDK 目录树时会超出路径长度限制，因此 Windows 主机需设置 <code>startup --output_user_root=C:/b</code>（<a href="./../integrations/bazel#on-a-windows-host">在 Windows 主机上</a>）。</p><h2 id="无绝对路径" tabindex="-1">无绝对路径 <a class="header-anchor" href="#无绝对路径" aria-label="Permalink to &quot;无绝对路径&quot;">​</a></h2><p>只有当动作命令行与动作产物都不包含特定于检出目录、output base 或沙盒的路径时，磁盘缓存或远程缓存才能跨目录与机器复用动作结果。<code>packages/bazel</code> 从所有编译、模块与链接动作中移除了绝对路径：</p><ul><li><strong>改写配置文件</strong>：<code>clang</code> 会将配置文件中的 <code>&lt;CFGDIR&gt;</code> 解析成绝对路径，并写入 <code>.d</code> 依赖文件。在仓库初始化阶段，<code>_bazel_cfg</code>（<code>bazel/repositories.bzl</code>）把每个目标平台的配置文件拷贝到 <code>cfg/</code> 下，将 <code>&lt;CFGDIR&gt;/..</code> 替换为 <code>external/&lt;repository&gt;</code>，同时写入 <code>-resource-dir=external/&lt;repository&gt;/lib/clang/&lt;major&gt;</code>；工具链则传入 <code>--no-default-config --config=external/&lt;repository&gt;/cfg/&lt;target&gt;.cfg</code>。</li><li><strong>相对工具前缀</strong>：编译与链接标志中加入 <code>-no-canonical-prefixes</code>，包装脚本（<code>scan_deps</code> 与 <code>dsym_link</code>）也按自身所在目录的相对路径定位工具。</li><li><strong>调试信息与二进制时间戳</strong>：每次编译传入 <code>-ffile-compilation-dir=.</code>；macOS 链接传入 <code>-Wl,-oso_prefix,.</code>；MinGW 链接传入 <code>-Wl,--no-insert-timestamp</code>；MSVC 目标平台在编译时传入 <code>-mno-incremental-linker-compatible</code> 与 <code>-gno-codeview-command-line</code>（避免 Windows 启动器路径写入 CodeView 记录），链接时传入 <code>-Wl,/Brepro</code>，用 <code>/pdbsourcepath:.</code> 设置 PDB 源码路径，且内嵌的 PDB 名称不带目录前缀（<a href="./../features/debugging#paths-in-debug-information">调试信息中的路径</a>）。</li><li><strong>C++20 模块文件</strong>：传入 <code>-Xclang -fmodule-file-home-is-cwd</code> 让 <code>.pcm</code> 文件记录相对于执行根目录的输入路径，并传入 <code>-Xclang -fmodules-embed-all-files</code>（<code>modules_embed_all_files</code>，默认开启），使带 <code>-g</code> 编译且 import 它的文件在沙盒内直接从 <code>.pcm</code> 中读取源码文本（<a href="./../features/modules#build-caches-and-modules">构建缓存与模块</a>）。</li><li><strong>预处理器时间戳</strong>：传入 <code>-Wno-builtin-macro-redefined</code>，并将 <code>__DATE__</code>、<code>__TIME__</code> 与 <code>__TIMESTAMP__</code> 定义为 <code>&quot;redacted&quot;</code>。</li></ul><p>macOS 主机上仍保留两处绝对路径：来自本机的 Xcode SDK 路径（<code>-isysroot</code>），以及原生 macOS 构建开启 sanitizer 特性时传入的 <code>-Wl,-rpath,&lt;absolute_root&gt;/lib/clang/&lt;major&gt;/lib/darwin</code>，用于让二进制程序在运行时找到 sanitizer 的 <code>.dylib</code>。</p><h2 id="每组主机与目标平台对应一个工具链" tabindex="-1">每组主机与目标平台对应一个工具链 <a class="header-anchor" href="#每组主机与目标平台对应一个工具链" aria-label="Permalink to &quot;每组主机与目标平台对应一个工具链&quot;">​</a></h2><p>由于每个主机压缩包都包含所有内置目标平台的 sysroot 与运行时库，模块会为每组 <code>(host, target)</code> 注册一个 <code>cc_toolchain</code>：<code>exec_compatible_with</code> 匹配主机操作系统与 CPU，<code>target_compatible_with</code> 匹配目标平台。Bazel 会选出同时匹配主机与 <code>--platforms</code> 目标平台的工具链，且只下载当前主机的工具链压缩包。</p><p>对于需要厂商 SDK 的目标平台（MSVC 目标平台，以及在 Linux 和 Windows 主机上构建的 macOS 目标平台），如果根 <code>MODULE.bazel</code> 中没有添加对应标签，构建会解析到一个在分析阶段立即报错退出的工具链，并打印所需添加的 <code>xclang.windows_sdk</code> 或 <code>xclang.macos_sdk</code> 标签。</p><p><code>@xclang//platforms:&lt;target&gt;</code> 中的平台声明了 <code>@platforms//os</code>、<code>@platforms//cpu</code> 以及 C 标准库约束（<code>@xclang//platforms/libc:glibc</code>、<code>:musl</code>、<code>:mingw</code>、<code>:macosx</code> 或 <code>:msvc</code>）。由于 musl 工具链（<code>//bazel/toolchains/musl:all</code>）与 MSVC 工具链（<code>//bazel/toolchains/msvc:all</code>）要求 <code>:musl</code> 或 <code>:msvc</code> 约束，且在 <code>MODULE.bazel</code> 中排在仅按操作系统与 CPU 匹配的 <code>//bazel/toolchains:all</code> 之前注册，不带 <code>libc</code> 约束的自定义 <code>platform</code> 在 Linux 上默认选用 <code>glibc</code>，在 Windows 上默认选用 MinGW。</p><h2 id="内置-rules-cc-工具链配置副本" tabindex="-1">内置 rules_cc 工具链配置副本 <a class="header-anchor" href="#内置-rules-cc-工具链配置副本" aria-label="Permalink to &quot;内置 rules_cc 工具链配置副本&quot;">​</a></h2><p>借助 <code>single_version_override</code> 补丁修改其他 Bazel 模块中的 <code>.bzl</code> 文件只在根 <code>MODULE.bazel</code> 中生效，这会迫使每个使用 <code>xclang</code> 的项目都在自身仓库中维护补丁文件；而直接对构建中的 <code>rules_cc</code> 仓库打补丁，一旦新版本 <code>rules_cc</code> 修改了邻近代码就会失效（如 <code>rules_cc</code> 0.2.28 的变更）。如果迁移到 <code>rules_cc</code> 基于规则的工具链 API，又得重新实现 <code>--macos_minimum_os</code>、<code>libtool</code>、死代码剥离与 sanitizer 特性。</p><p>因此，<code>packages/bazel/bazel/unix_cc_toolchain_config.bzl</code> 直接保存了一份 xclang 自己的 <code>rules_cc</code> 0.2.28 <code>unix_cc_toolchain_config.bzl</code> 副本。这份副本只从 <code>rules_cc</code>、<code>apple_support</code> 与 <code>bazel_skylib</code> 加载公开文件，无需下游项目配置 override 即可兼容 <code>rules_cc</code> 0.2.25 及以上版本。</p><p>相比上游 <code>rules_cc</code>，xclang 的配置与 <code>bazel/toolchain.bzl</code> 增加了以下改动：</p><ul><li>MinGW 与 MSVC 目标平台使用 <code>.exe</code> 和 <code>.dll</code> 作为产物名称，且在 Windows 上不传入 <code>rpath</code>；</li><li>支持 MSVC 目标平台：使用 GNU 风格的 <code>clang</code> 驱动配合 <code>lld-link</code> 标志，默认开启 <code>-std=c++17</code>，禁用 PIC，支持生成 PDB（<code>generate_pdb_file</code>）、选择 CRT（<code>dynamic_link_msvcrt</code>、<code>debug_msvcrt</code>）以及布置运行时 DLL（<code>copy_dynamic_libraries_to_binary</code>）；</li><li>默认静态链接 <code>cc_library</code> 依赖（<a href="#static-by-default">见下文</a>）；</li><li>外部仓库的头文件以 <code>-isystem</code> 传入（<code>external_include_paths</code> 默认开启），避免第三方依赖的警告导致构建失败；</li><li>sanitizer 标志：启用 <code>asan</code> 时切换到预编译的 ASan <code>libc++</code>，启用 <code>--@xclang//runtimes:source</code> 时从 <code>libc++/src</code> 构建 <code>libc++</code>、<code>libc++abi</code> 与 <code>libunwind</code>，并在 glibc Linux 目标平台上支持 MemorySanitizer（<code>msan</code>）（<a href="./../features/runtimes-from-source">从源码构建运行时库</a>）；</li><li><code>gc_sections</code> 在 Linux 的 <code>opt</code> 构建下默认开启，在 Windows 上默认关闭（<a href="./windows#gc-sections-and-static-initializers"><code>gc-sections</code> 与静态初始化器</a>）；</li><li>macOS 链接除非开启 <code>macos_default_link_flags</code>，否则不传 <code>-fobjc-link-runtime</code>；<code>--macos_minimum_os</code> 下限锁定为 <code>13.0</code>；在 Linux 与 macOS 上将库目标文件夹在 <code>--start-lib</code> 与 <code>--end-lib</code> 之间传入（避免 Bazel 将时间戳归零后 <code>dsymutil</code> 混淆静态库中的同名成员）；由 <code>dsym_link</code> 在链接阶段调用 <code>dsymutil --linker classic</code> 生成 <code>.dSYM</code> 包（避开 LLVM 23 并行链接器生成的会导致 <code>atos</code> 崩溃的 DWARF 5 行号表；<a href="./../features/debugging#why-a-dsym-comes-from-the-link">为什么在链接阶段生成 dSYM</a>）；</li><li>按二进制格式区分的符号剥离（ELF 与 COFF 使用 <code>--strip-unneeded</code>，Mach-O 使用 <code>--strip-all</code> 并在 <code>opt</code> 下配合 <code>-Wl,-no_exported_symbols</code>；<a href="./../features/debugging#strip">剥离符号</a>）；</li><li>在 macOS 上与 Linux 和 Windows 一样，将库的 <code>defines</code> 传给 C++20 模块编译与 <code>clang-scan-deps</code> 依赖扫描。</li></ul><h2 id="默认静态链接" tabindex="-1">默认静态链接 <a class="header-anchor" href="#默认静态链接" aria-label="Permalink to &quot;默认静态链接&quot;">​</a></h2><p>在 <code>rules_cc</code> 的默认配置下，只要开启了 <code>supports_dynamic_linker</code>，<code>cc_test</code> 目标的 <code>cc_library</code> 依赖就会分别链接成独立的共享库。由于 xclang 链接的每个共享库都带有各自私有的静态 <code>libc++</code>（<a href="./hermeticity#one-libc-per-shared-object">每个共享对象独立的 <code>libc++</code></a>），将每个 <code>cc_library</code> 链接成共享对象会让每个库都持有一份独立的 <code>libc++</code> 实例（这曾导致 <code>kotatsu</code> 的测试在启动时因重复释放内存而崩溃，并在 Windows 上链接失败）。</p><p>因此，工具链配置默认关闭 <code>supports_dynamic_linker</code>，使 <code>cc_library</code> 目标静态链接进可执行文件与测试。<code>cc_binary(linkshared = True)</code> 仍会生成共享库（<code>libfoo.so</code>、<code>libfoo.dylib</code>、<code>foo.dll</code>），而在 Linux 目标平台上设置 <code>features = [&quot;supports_dynamic_linker&quot;]</code> 可以重新开启动态链接。</p><h2 id="作为外部仓库的厂商-sdk" tabindex="-1">作为外部仓库的厂商 SDK <a class="header-anchor" href="#作为外部仓库的厂商-sdk" aria-label="Permalink to &quot;作为外部仓库的厂商 SDK&quot;">​</a></h2><p>MSVC 目标平台需要微软的 CRT、STL 与 Windows SDK，Linux 和 Windows 主机上的 macOS 目标平台需要 Apple 的 macOS SDK。直接调用 <code>clang</code> 或使用 CMake 时，<a href="./../reference/xclang-command"><code>xclang</code> 命令</a>会把拉取的 SDK 解压到 <code>&lt;toolchain&gt;/sdk/</code>；但 Bazel 构建不能向工具链仓库写入文件，而且必须把每个 SDK 文件都声明为构建输入。<code>bazel/sdk.bzl</code> 将每个厂商 SDK 作为独立的外部仓库管理：</p><ul><li><strong>在根 <code>MODULE.bazel</code> 中接受许可条款</strong>：只有根模块（<code>mod.is_root</code>）中的 <code>xclang.windows_sdk</code> 与 <code>xclang.macos_sdk</code> 标签会生效，依赖模块不能替下游使用者接受厂商许可证。</li><li><strong>Bazel 负责下载，<code>xclang</code> 负责解压</strong>：仓库规则运行 <code>xclang sdk packages &lt;vendor&gt; --json</code> 查询锁定的安装包 URL、大小与 <code>sha256</code> 摘要，调用 <code>rctx.download</code> 将安装包下载到 Bazel 共享仓库缓存中（自动应用已配置的 Bazel 镜像、代理或 <code>--distdir</code>），随后调用 <code>xclang sdk fetch &lt;vendor&gt; --accept-license --cache downloads --sdk-dir sdk</code> 解压归档，并在大小写敏感的文件系统上创建大小写折叠符号链接。如果 Apple 下架了某个锁定的 macOS Command Line Tools 安装包，<code>xclang sdk fetch</code> 会在 Apple 软件目录中定位替代安装包，并按内容摘要校验解压出的 SDK（<a href="./macos#packages-apple-withdraws-and-content-digests">Apple 下架的安装包</a>）。</li><li><strong>生成 <code>sdk.cfg</code></strong>：每个 SDK 仓库都会写出带执行根目录相对路径的 <code>sdk.cfg</code>（macOS 为 <code>-isysroot external/&lt;repo&gt;/sdk/&lt;name&gt;</code>，MSVC 目标平台为改写后指定 MSVC 与 Windows SDK 版本目录的 <code>&lt;arch&gt;-pc-windows-msvc.cfg</code>），工具链的 <code>cfg/&lt;target&gt;.cfg</code> 再经由 <code>@../../&lt;sdk_repo&gt;/sdk.cfg</code> 引入它。</li><li><strong>按架构惰性拉取仓库</strong>：<code>xclang_windows_sdk_x86_64</code>（下载大小 310 MB）、<code>xclang_windows_sdk_aarch64</code>（下载大小 380 MB）与 <code>xclang_macos_sdk</code> 只有在构建面向对应平台时才会拉取。</li><li><strong>拆分编译与链接 filegroup</strong>：SDK 仓库中的 <code>BUILD.bazel</code> 用 <code>glob()</code> 导出 <code>:compiler_files</code> 与 <code>:linker_files</code>。对于 macOS SDK，<code>_unlink_cycles</code> 会在 <code>glob()</code> 运行前移除目录符号链接环（如 <code>Ruby.framework</code> 的 <code>Headers/ruby/ruby -&gt; .</code>）；<code>:compiler_files</code> 布置头文件与 framework（15,000 个文件），<code>:linker_files</code> 布置 <code>.tbd</code> 桩文件与 <code>SDKSettings.*</code>（9,800 个文件）。对于 MSVC 目标平台，<code>:compiler_files</code> 声明 7,300 个头文件与链接，<code>:linker_files</code> 声明 1,300 个库文件。</li></ul><h2 id="registry" tabindex="-1">Registry <a class="header-anchor" href="#registry" aria-label="Permalink to &quot;Registry&quot;">​</a></h2><p><code>published.yml</code> 基于已发布的发版产物构建并测试发版标签后，<code>node packages/bazel/bazel.ts archive</code> 会构建 <code>xclang-bazel-&lt;version&gt;.tar.gz</code>，并将模块发布到 <a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a>。<code>bazel.ts</code> 在内存中以确定性方式构造 <code>ustar</code> 归档——条目排序、权限设为 <code>0755</code>/<code>0644</code>、所有者与时间戳字段清零、gzip 的 OS 头字节设为 <code>255</code>——从而保证生成的 registry 压缩包在任何主机上都逐字节一致。</p>',29)])])}const _=o(l,[["render",i]]);export{m as __pageData,_ as default};
